    // Bit-exact port of YRMath::sqrt (0x4cac40 - 0x4cac59). Input is the
    // same double the fild at 0x59cff3 produces; output is the float the
    // fstp at 0x59cfff stores.
    inline float Sqrt(double a1)
    {
        if (a1 == 0.0)
            return 0.0f;
        if (a1 <= 0.0)
            a1 = -a1;
        union { float f; unsigned int u; } cvt;
        cvt.f = static_cast<float>(a1);
        unsigned int mant = cvt.u & 0x7FFFFFu;
        int e = static_cast<int>(cvt.u >> 23) - 127;
        if (e & 1) mant |= 0x800000u;
        cvt.u = (((e >> 1) + 127) << 23) + kTable[mant >> 10];
        return cvt.f;
    }
